def sort_even(l: list):
    even_indices_values = sorted(l[i] for i in range(0, len(l), 2))
    result = []
    even_index_counter = 0
    for i in range(len(l)):
        if i % 2 == 0:
            result.append(even_indices_values[even_index_counter])
            even_index_counter += 1
        else:
            result.append(l[i])
    return result
